#!/bin/bash

# Flutter Web Build Script for Netlify Deployment
# Usage: ./build_for_netlify.sh

set -e  # Exit on error

echo "🚀 Starting Flutter Web Build for Netlify..."
echo ""

# Colors for output
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
NC='\033[0m' # No Color

# Step 1: Clean
echo -e "${BLUE}Step 1: Cleaning previous builds...${NC}"
flutter clean
echo "✅ Clean complete"
echo ""

# Step 2: Get dependencies
echo -e "${BLUE}Step 2: Getting dependencies...${NC}"
flutter pub get
echo "✅ Dependencies installed"
echo ""

# Step 3: Build for web
echo -e "${BLUE}Step 3: Building Flutter web app (release mode)...${NC}"
flutter build web --release --web-renderer canvaskit
echo "✅ Build complete"
echo ""

# Step 4: Verify build output
echo -e "${BLUE}Step 4: Verifying build output...${NC}"
if [ -d "build/web" ]; then
    echo "✅ Build directory exists: build/web"
